import{_ as t,d as o,e as a,x as i}from"./chunks/framework.BRr8VP3a.js";const h=JSON.parse('{"title":"A.1 HV01 Structural Domain (Full Interface Card)","description":"","frontmatter":{"title":"A.1 HV01 Structural Domain (Full Interface Card)","xkChars":0,"xkWords":1213},"headers":[],"relativePath":"en/theory/appendix-a/a-01.md","filePath":"en/theory/appendix-a/a-01.md"}'),n={name:"en/theory/appendix-a/a-01.md"};function r(d,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<div class="theory-source"><h1 id="section-a-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.1</span><span class="xk-num__gap"></span></span>HV01 Structural Domain (Full Interface Card) <a class="header-anchor" href="#section-a-1" aria-label="Permalink to &quot;A.1 HV01 Structural Domain (Full Interface Card) {#section-a-1}&quot;">​</a></h1><p>A. Identity, Proposition, and Scope</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Interface ID (<code>id</code>)</td><td>HV01</td></tr><tr><td>Qualified ID (<code>qualified_id</code>)</td><td><code>human_variable:HV01</code></td></tr><tr><td>Name (<code>name</code>)</td><td>Structural Domain</td></tr><tr><td>Claim type (<code>claim_type</code>)</td><td>H</td></tr><tr><td>Contract role (<code>contract_role</code>)</td><td><code>human_variable_interface</code></td></tr><tr><td>Proposition (<code>proposition</code>)</td><td>D0 declares only a candidate human object. Register a limited effective structural domain within the instance’s scope only if a pre-registered G1-instance shows that the candidate grouping achieves an out-of-sample or extrapolation gain above the threshold on the preselected outcome relative to a matched N0.</td></tr><tr><td>Scope (<code>scope</code>)</td><td>Relationships, teams, organizations, institutions, and public issues</td></tr><tr><td>Conditions for suspension (<code>pause_condition</code>)</td><td>The object, boundary, scale, time window, or basis for treating it as the same object is insufficient for the selected route. When formal G1 support is sought, the corresponding null model or instance contract is incomplete</td></tr></tbody></table></div><p>B. Formal Dependencies and Limits on Conclusions</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Inferential dependencies (<code>inferential_requires</code>)</td><td>1. D0</td></tr><tr><td>Protocol dependencies (<code>protocol_requires</code>)</td><td>1. E1<br>2. EVIDENCE<br>3. SOURCE</td></tr><tr><td>Qualification/specialization (<code>specializes</code>)</td><td>None (empty set)</td></tr><tr><td>References to applicable objects (<code>applies_to</code>)</td><td>None (empty set)</td></tr><tr><td>Conditional support routes (<code>conditional_support_routes</code>)</td><td>1. route_id=HV01-R0-candidate-object;<br>claim_level=candidate_description;<br>when=The D0 object contract is complete, but there is not yet an eligible G1-instance with result_state=supported;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Register a candidate human object, the set of materials, boundary disputes, and the need for further G1 evidence;<br>result_ceiling=Candidate object description only. A reference to the object with its boundary and uncertainty may be supplied to HV02–HV11. Do not treat the reference as an effective structural domain supported by G1.<br>2. route_id=HV01-R1-effective-domain;<br>claim_level=descriptive_classification;<br>when=A pre-registered G1-instance for the same object, scale, window, K, and extrapolation unit is supported;<br>additional_inferential_requires=G1-instance;<br>additional_protocol_requires=E4;<br>allowed_conclusion=Register the limited effective structural domain, strength of support for the grouping gain, robustness of that gain to tested boundary perturbations, and window of applicability within the scope of that instance;<br>result_ceiling=Limited to the pre-registered SP/T/K and generalization_unit. Do not draw conclusions about the object’s ultimate nature, a unified will, or authorization.</td></tr><tr><td>Permitted inferences (<code>allowed_inference</code>)</td><td>1. R0 may register a candidate object, boundary disputes, and limited descriptive references<br>2. Register only the limited effective structural domain supported by the gain, and the strength of support for the grouping gain, within the G1-instance’s pre-registered object, scale, window, outcome, and extrapolation unit</td></tr><tr><td>Prohibited leaps (<code>prohibited_leap</code>)</td><td>1. Inferring an objective community from naming it. 2. Inferring a common will from shared circumstances</td></tr></tbody></table></div><p>C. Nine-Axis Scale and Object Contract</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Nine-axis scale profile (<code>scale_profile</code>)</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A=Aggregation level covers relational or event units, the candidate member population, distributions inside and outside the boundary, and grouping rules. X=Spatial extent covers common locations, organizational boundaries, digital platforms, and external environments across domains. T=Time span covers the identification window, cycles of membership change, and boundary history. O=Organizational level covers roles, teams, organizations, institutions, and governance ecologies. C=Causal level covers originating events, interaction mechanisms, meso-level relational structures, and institutional and systemic conditions. R=Resolution covers original interactions, event sequences, individual member cases, boundary distributions, metrics, and summaries. Record compression loss as well. I=Scope of influence covers direct members, people excluded, people indirectly affected, second-order spillovers, and positions across domains and generations. N=Network topology scope covers membership relations, boundary connections, isolated points, and bridging across domains. J=Scope of jurisdiction and authorization requires separate authorization records for naming the object, adopting the boundary, and subsequent action. For an inapplicable axis, record the reason for <code>not_applicable</code></td></tr><tr><td>Effective object (<code>effective_object</code>)</td><td>A candidate object declared by D0. Register it as a limited effective structural domain within the instance’s scope only if the pre-registered G1-instance passes the threshold test relative to a matched N0</td></tr><tr><td>Scale invariants (<code>scale_invariants</code>)</td><td>1. Object contract. 2. Participating and affected positions</td></tr><tr><td>Required additions for scale elevation (<code>required_scale_additions</code>)</td><td>1. Units and population<br>2. Representativeness<br>3. J axis<br>4. Positions with low visibility</td></tr><tr><td>What changes with scale (<code>changing_semantics</code>)</td><td>1. Effective membership, relationships, and what counts as the same object can change with scale</td></tr><tr><td>Inapplicable objects (<code>non_applicable_objects</code>)</td><td>1. Nonhuman systems without intent, institutions, or interfaces for responsibility</td></tr><tr><td>Prohibited elevations (<code>forbidden_elevation</code>)</td><td>1. Treating a local group as directly representative of all affected people</td></tr></tbody></table></div><p>D. State, Evidence, and Variable Flows</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>State set (<code>state</code>)</td><td>1. Candidate. 2. Identifiable. 3. Boundary disputed. 4. Does not hold</td></tr><tr><td>Observables (<code>observables</code>)</td><td>1. Differences in relationship density and constraints inside and outside the boundary<br>2. Records of members entering, exiting, or being excluded<br>3. Repeated co-occurrence of common problems, resource channels, or institutional rules<br>4. Whether the grouping gain remains stable after changing the grouping rule</td></tr><tr><td>Evidence requirements (<code>evidence</code>)</td><td>1. D0 candidate object and records used to determine whether it remains the same object<br>2. The G1-instance pre-registration and matched N0<br>3. Training results and out-of-sample or extrapolation results<br>4. Comparison of gains for the candidate and competing groupings</td></tr><tr><td>Input dependencies and interface content (<code>input_dependencies</code>)</td><td>1. D0 provides only candidate object fields and does not establish the structure<br>2. Pre-registered G1-instance, matched N0, threshold, model class, and sample or extrapolation unit<br>3. Observation positions, competing groupings, and the E1 protocol</td></tr><tr><td>Output effects and variable flows (<code>output_effects</code>)</td><td>1. R0 supplies the other variables with a candidate object reference, boundary, time window, and uncertainty. R1 additionally supplies the limited effective scope supported by G1<br>2. Preserve grounds for both the object’s existence and domain facts separately from grouping gains</td></tr><tr><td>Time window and lag (<code>time_window_and_lag</code>)</td><td>Register the identification window, boundary changes, and lags in membership changes</td></tr><tr><td>Uncertainty (<code>uncertainty</code>)</td><td>Record boundary disputes, absent members, and observation coverage</td></tr><tr><td>Local exclusion zone (<code>local_exclusion_zone</code>)</td><td>The aggregate must not represent positions where people cannot express themselves safely or that were not sampled</td></tr><tr><td>Affected positions (<code>affected_positions</code>)</td><td>1. Members. 2. People excluded. 3. Cost bearers outside the boundary</td></tr></tbody></table></div><p>E. Uptake, Responsibility, Normative Status, Ceilings, and Correction</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Uptake carriers (<code>carrier</code>)</td><td>1. Relationship network. 2. Organizational boundary. 3. Institutional records</td></tr><tr><td>Responsible parties (<code>responsible_subject</code>)</td><td>1. The analyst who proposes the structural domain judgment<br>2. The decision maker who uses the judgment</td></tr><tr><td>Normative status (<code>normative_status</code>)</td><td>A descriptive H-World interface. It confers no normative justification</td></tr><tr><td>Judgment ceiling (<code>judgment_ceiling</code>)</td><td>A limited effective structural domain at the level of explanation may be registered only if the G1-instance passes, and only for the pre-registered object, scale, window, outcome, and extrapolation unit. Otherwise no support from a grouping gain is registered, while the candidate object reference and object facts with separate grounds are retained as usual</td></tr><tr><td>Action ceiling (<code>action_ceiling</code>)</td><td>This variable produces only descriptions of candidate structural domains, boundary disputes, and needs for more evidence. It does not authorize inclusion, exclusion, or action. Any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures</td></tr><tr><td>Counterexamples (<code>counterexamples</code>)</td><td>1. People repeatedly present in the same place lack stable relationships or common constraints<br>2. A group defined by the analyst disappears as soon as the grouping rule changes</td></tr><tr><td>Appeal (<code>appeal</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, members and people at affected positions can challenge the boundary, representativeness, and the object’s identity criterion through a safe, accessible channel with anti-retaliation protection. This triggers review independent of the original naming or decision chain</td></tr><tr><td>Rollback (<code>rollback</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, once rollback is authorized, the designated responsible party must within the stated deadline actually revoke the structural domain registration, remove its effect on the scope of downstream objects, and return it to a candidate grouping. Object facts with separate grounds are not revoked along with it. Preserve versions and verification of completion</td></tr></tbody></table></div></div>',1)])])}const b=t(n,[["render",r]]);export{h as __pageData,b as default};
